export function polishDialogue(d){
if(d["chapterEnd"]?.[8])d["chapterEnd"][8][1]="到了灰石驿站，把那件事办完，你就放我回去。别到时候又说还要等。";
if(d["saintSealTalk"]?.[2])d["saintSealTalk"][2][1]="这道封印到底什么时候解？腕上一直疼，你总得给我一个准话。";
if(d["saintSealTalk"]?.[6])d["saintSealTalk"][6][1]="那就到驿站再说。兜帽我自己戴，别碰我。";
if(d["saintRoadEarly"]?.[5])d["saintRoadEarly"][5][1]="前面是北门。别停在路口。";
if(d["saintFarewellWait"]?.[4])d["saintFarewellWait"][4][1]="还有，别向他们打听我的事。我不认识他们，也没答应见谁。";
if(d["saintRoadTalk"]?.[6])d["saintRoadTalk"][6][1]="绷带给我就行。买完了快走，别又往别的铺子绕。";
if(d["saintCave"]?.[1])d["saintCave"][1][1]="那台机器缺机芯。拿到就走。";
if(d["sisterAfterBell"]?.[6])d["sisterAfterBell"][6][1]="不是故意绕你。这封信只许交到驿站，名字我现在不能说。";
if(d["waterworksLog"]?.[1])d["waterworksLog"][1][1]="「后槽可单独抽出机芯。前槽刻录筒与指环架共用细簧：拆下一端时，另一端会被回弹压坏。先选好要留哪件。」";
}
